import{_ as a,C as n,o as i,c as s,j as e,a as d,E as o,a3 as l}from"./chunks/framework.D4-ViStF.js";const y=JSON.parse('{"title":"象数易理篇之三：八卦类象与万物属类","description":"建立八卦与天时、地理、人物、器物等万物之间的取象词典。","frontmatter":{"title":"象数易理篇之三：八卦类象与万物属类","description":"建立八卦与天时、地理、人物、器物等万物之间的取象词典。","category":"学习计划 · 第一阶段"},"headers":[],"relativePath":"yijing/meihua-yishu/xiang-shu-li/trigram-correspondence.md","filePath":"yijing/meihua-yishu/xiang-shu-li/trigram-correspondence.md","lastUpdated":1787730063000}'),g={name:"yijing/meihua-yishu/xiang-shu-li/trigram-correspondence.md"};function h(p,t,b,c,u,m){const r=n("DaoTextReading");return i(),s("div",null,[t[0]||(t[0]=e("h1",{id:"【象数易理篇之三】八卦类象与万物属类",tabindex:"-1"},[d("【象数易理篇之三】八卦类象与万物属类 "),e("a",{class:"header-anchor",href:"#【象数易理篇之三】八卦类象与万物属类","aria-label":'Permalink to "【象数易理篇之三】八卦类象与万物属类"'},"​")],-1)),t[1]||(t[1]=e("h2",{id:"📜-原文",tabindex:"-1"},[d("📜 原文 "),e("a",{class:"header-anchor",href:"#📜-原文","aria-label":'Permalink to "📜 原文"'},"​")],-1)),o(r,{colophon:"八卦类象 · 万物属类",tone:"ink",sections:[{id:"sec-01",label:"八卦类象",showLabel:!0,sentences:[["乾：玄黄、大赤色、金玉、宝珠、镜、狮、圆物、木果、贵物、冠、象、马、天鹅、刚物。"],["坎：水、带子带核之物、豕鱼、弓轮、水具、水中之屋、盐、酒、黑色。"],["艮：土石、黄色、虎、狗、土中之物、瓜果、百禽、鼠、",{text:"黔喙",glossary:"g12"},"之属。"],["震：竹木、青碧绿色、龙、蛇、苇、竹木乐器、草、",{text:"蕃鲜",glossary:"g03"},"之物。"],["巽：木、蛇、长物、青碧绿色、山木之禽鸟、香、鸡、直物、竹木之器、工巧之器。"],["离：火、文书、干戈、雉、龟、蟹、槁木、甲胄、螺、蚌、鳖、赤色。"],["坤：土、方物、五谷、柔物、丝绵、百禽、牛、布帛、舆、金、瓦器、黄色。"],["兑：金刃、金器、乐器、泽中之物、白色、有口缺之物、羊。"]]},{id:"sec-02",label:"☰ 乾卦　一　金",showLabel:!0,sentences:[["天时：天、冰、雹、",{text:"霰",glossary:"g01"},"。"],["地理：西北方、京都、大郡、形胜之地、高亢之所。"],["人物：君、父、大人、老人、长者、官宦、名人、公门人。"],["人事：刚健武勇、果决、多动少静、高上下屈。"],["身体：首、骨、肺。"],["时序：秋、九十月之交、戌亥年月日时、一四九年月日时。"],["动物：马、天鹅、狮、象。"],["静物：金玉、宝珠、圆物、水果、刚物、冠、镜。"],["屋舍：",{text:"公廨",glossary:"g02"},"、楼台、高堂、大厦、驿舍、西北向之居。"],["家宅：秋占宅兴隆、夏占有祸、冬占冷落、春占吉利。"],["婚姻：贵官之眷、有声名之家、秋占宜成、冬夏占不利。"],["饮食：马肉、珍味、多骨、肝肺、干肉、水果、诸物之首、圆物、辛辣之物。"],["生产：易生、秋占生贵子，夏占有损，坐宜向西北。"],["求名：有名、宜随朝内任、刑官、武职、掌权、天使、驿官、宜西北方之任。"],["谋旺：有成、利公门、宜动中有财、夏占不成、冬占多谋少遂。"],["交易：宜金、玉珍宝珠贵货、易成、夏占不利。"],["求利：有财、金、玉之利、公门中得财、秋占大利、夏占损财、冬占无财。"],["出行：利于出行、宜入京师、利西北之行、夏占不利。"],["谒见：利见大人、有德行之人、宜见官贵、可见。"],["疾病：头面之疾、肺疾、筋骨疾、上焦疾、夏占不安。"],["官讼：健讼、有贵人助、秋占得胜、夏占失理。"],["坟墓：宜向西北、宜干山气脉、宜天穴、宜高、秋占出贵、夏占大凶。"],["方道：西北。"],["五色：大赤色、玄色。"],["姓字：带金旁者、",{text:"商音",glossary:"g17"},"、行位一四九。"],["数目：一、四、九。"],["五味：辛、辣。"]]},{id:"sec-03",label:"☷ 坤卦　八　土",showLabel:!0,sentences:[["天时：云阴、雾气。"],["地理：田野、乡里、平地、西南方。"],["人物：老母、后母、农夫、乡人、众人、大腹人。"],["人事：吝啬、柔顺、懦弱、众多。"],["身体：腹、脾、胃、肉。"],["时序：辰戌丑未月、未申年月日时、八五十月日。"],["静物：方物、柔物、布帛、丝绵、五谷、舆釜、瓦器。"],["动物：牛、百兽、牝马。"],["屋舍：西南向、村居、田舍、矮屋、土阶、仓库。"],["家宅：安稳、多阴气、春占宅舍不安。"],["饮食：牛肉、土中之物、甘味、野味、五谷之味、芋笋之物、腹脏之物。"],["婚姻：利于婚姻、宜税产之家、乡村之家、或寡妇之家、春占不利。"],["生产：易产、春占难产、有损、或不利于母、坐宜西南方。"],["求名：有名、宜西南方或教官、农官守土之职、春占虚名。"],["交易：宜利交易、宜田土交易、宜五谷、利贱货、重物、布帛、静中有财、春占不利。"],["求利：有利、宜土中之利、贱货重物之利、静中得财、春占无财、多中取利。"],["谋旺：利求谋、乡里求谋、静中求谋、春占少遂、或谋于妇人。"],["出行：可行、宜西南行、宜往乡里行、宜陆行、春占不宜行。"],["谒见：可见、利见乡人、宜见亲朋或阴人、春不宜见。"],["疾病：腹疾、脾胃之疾、饮食停伤、谷食不化。"],["官讼：理顺、得众情、讼当解散。"],["坟墓：宜向西南之穴、平阳之地、近田野、宜低葬、春不可葬。"],["姓字：",{text:"宫音",glossary:"g17"},"、带土姓人、行位八五十。"],["数目：八、五、十。"],["方道：西南。"],["五味：甘。"],["五色：黄、黑。"]]},{id:"sec-04",label:"☳ 震卦　四　木",showLabel:!0,sentences:[["天时：雷。"],["地理：东方、树木、闹市、大途、竹林、草木茂盛之所。"],["人物：长男。"],["人事：起动、怒、虚惊、鼓动噪、多动少静。"],["身体：足、肝、发、声音。"],["时序：春三月、卯年月日时、四三八月日。"],["静物：木竹、",{text:"萑苇",glossary:"g04"},"、乐器（属竹木者）、花草繁鲜之物。"],["动物：龙、蛇。"],["屋舍：东向之居、山林之处、楼阁。"],["家宅：宅中不时有虚惊、春冬吉、秋占不利。"],["饮食：蹄、肉、山林野味、鲜肉、果酸味、菜蔬。"],["婚姻：可、有成、声名之家、得长男之婚、秋占不宜婚。"],["求利：山林竹木之财、动处求财、或山林、竹木茶货之利。"],["求名：有名、宜东方之任、施号发令之职、掌刑狱之官、竹茶木税课之任、或闹市司货之职。"],["生产：虚惊、胎动不安、头胎必生男、坐宜东向、秋占必有损。"],["疾病：足疾、肝经之疾、惊怖不安。"],["谋旺：可旺、可求、宜动中谋、秋占不遂。"],["交易：利于成交、秋占难成、动而可成、山林、木竹茶货之利。"],["官讼：健讼、有虚惊、行移取甚反复。"],["谒见：可见、在山林之人、利见宜有声名之人。"],["出行：宜行、利于东方、利山林之人、秋占不宜行、但恐虚惊。"],["坟墓：利于东向、山林中穴、秋不利。"],["姓字：",{text:"角音",glossary:"g17"},"、带木姓人、行位四八三。"],["数目：四、八、三。"],["方道：东。"],["五味：甘、酸味。"],["五色：青、绿、碧。"]]},{id:"sec-05",label:"☴ 巽卦　五　木",showLabel:!0,sentences:[["天时：风。"],["地理：东南方之地、草木茂秀之所、花果菜园。"],["人物：长女、秀士、寡妇之人、山林仙道之人。"],["人事：柔和、不定、鼓舞、利市三倍、进退不果。"],["身体：",{text:"肱",glossary:"g06"},"、股、气、风疾。"],["时序：春夏之交、三五八之时月日、辰巳月日时。"],["静物：木香、绳、直物、长物、竹木、工巧之器。"],["动物：鸡、百禽、山林中之禽、虫。"],["屋舍：东南向之居、寺观楼台、山林之居。"],["家宅：安稳利市、春占吉、秋占不安。"],["饮食：鸡肉、山林之味、蔬果酸味。"],["婚姻：可成、宜长女之婚、秋占不利。"],["生产：易生、头胎产女、秋占损胎、宜向东南坐。"],["求名：有名、宜文职有",{text:"风宪",glossary:"g05"},"之力、宜为",{text:"风宪",glossary:"g05"},"、宜茶果竹木税货之职、宜东南之任。"],["求利：有利三倍、宜山林之利、秋占不利、竹货木货之利。"],["交易：可成、进退不一、利山林交易、山林木茶之利。"],["谋旺：可谋旺、有财可成、秋占多谋少遂。"],["出行：可行、有出入之利、宜向东南行、秋占不利。"],["谒见：可见、利见山林之人、利见文人秀士。"],["疾病：股",{text:"肱",glossary:"g06"},"之疾、风疾、肠疾、中风、寒邪、气疾。"],["姓字：",{text:"角音",glossary:"g17"},"、草木旁姓氏、行位五三八。"],["官讼：宜和、恐遭",{text:"风宪",glossary:"g05"},"之责。"],["坟墓：宜东南方向、山林之穴、多树木、秋占不利。"],["数目：五、三、八。"],["方道：东南。"],["五味：酸味。"],["五色：青、绿、碧、洁白。"]]},{id:"sec-06",label:"☵ 坎卦　六　水",showLabel:!0,sentences:[["天时：月、雨、雪、霜、露。"],["地理：北方、江湖、溪涧、泉井、卑湿之地（沟渎、池沼、凡有水处）。"],["人物：中男、江湖之人、舟人、",{text:"资贼",glossary:"g07"},"。"],["人事：险陷卑下、外示以柔、内序以利、漂泊不成、随波逐流。"],["身体：耳、血、肾。"],["时序：冬十一月、子年月日时、一六月日。"],["静物：水带子、带核之物、弓轮、",{text:"矫揉之物",glossary:"g08"},"、酒器、水具。"],["屋舍：向北之居、近水、水阁、江楼、花酒长器、宅中混地之处。"],["饮食：豕肉、酒、冷味、海味、汤、酸味、宿食、鱼、带血、掩藏、有带核之物、水中之物、多骨之物。"],["家宅：不安、暗昧、防盗。"],["婚姻：利中男之婚、宜北方之婚、辰戌丑未月婚不可。"],["生产：难产有险、宜次胎、中男、辰戌丑未月有损、宜北向。"],["求名：艰难、恐有灾险、宜北方之任、鱼盐河泊之职。"],["求利：有财失、宜水边财、恐有失陷、宜鱼盐酒货之利、防遗失、防盗。"],["交易：不利成交、恐防失陷、宜水边交易、宜鱼盐货之交易、或点水人之交易。"],["谋旺：不宜谋旺、不能成就、秋冬占可谋旺。"],["出行：不宜远行、宜涉舟、宜北方之行、防盗、恐遇险陷溺之事。"],["谒见：难见、宜见江湖之人、或有水旁姓氏之人。"],["疾病：耳痛、心疾、感寒、肾疾、胃冷、水泻、",{text:"痼冷",glossary:"g09"},"之病、血病。"],["官讼：不利、有阴险、有失、因讼、失陷。"],["坟墓：宜北向之穴、近水傍之墓、不利葬。"],["姓字：",{text:"羽音",glossary:"g17"},"、点水旁之姓氏、行位一六。"],["数目：一、六。"],["方道：北方。"],["五味：咸、酸。"],["五色：黑。"]]},{id:"sec-07",label:"☲ 离卦　三　火",showLabel:!0,sentences:[["天时：日、电、虹、霓、霞。"],["地理：南方、",{text:"干亢",glossary:"g10"},"之地、窖灶、炉冶之所、刚燥厥地、其地面阳。"],["人物：中女、文人、大腹、目疾人、甲胄之士。"],["人事：文画之所、聪明才学、相见虚心、书事。"],["身体：目、心、上焦。"],["时序：夏五月、午火年月日时、三二七日。"],["静物：火、书、文、甲胄、干戈、槁衣、干燥之物、赤色之物。"],["动物：雉、龟、鳖、蟹、螺、蚌。"],["屋舍：南舍之居、阳明之宅、明窗、虚室。"],["家宅：安稳、平善、冬占不安、克体主火灾。"],["饮食：雉肉、煎炒、烧炙之物、干脯之体、热肉。"],["婚姻：不成、利中女之婚、夏占可成、冬占不利。"],["生产：易生、产中女、冬占有损、坐宜向南。"],["求名：有名、宜南方之职、文官之任、宜炉冶亢场之职。"],["求利：有财宜南方求、有文书之财、冬占有失。"],["谋旺：可以谋旺、宜文书之事。"],["交易：可成、宜有文书之交易。"],["出行：可行、宜向南方、就文书之行、冬占不宜行、不宜行舟。"],["谒见：可见南方人、冬占不顺、秋见文书考案之士。"],["官讼：易散、文书动、辞讼明辨。"],["疾病：目疾、心疾、上焦热病、夏占伏暑、时疫。"],["坟墓：南向之幕、无树木之所、阳穴。夏占出文人、冬占不利。"],["姓字：",{text:"征音",glossary:"g17"},"、立人旁士姓氏、行位三二七。"],["数目：三、二、七。"],["方道：南。"],["五色：赤、紫、红。"],["五味：苦。"]]},{id:"sec-08",label:"☶ 艮卦　七　土",showLabel:!0,sentences:[["天时：云、雾、",{text:"山岚",glossary:"g13"},"。"],["地理：山径路、近山城、丘陵、坟墓、东北方。"],["人物：少男、闲人、山中人。"],["人事：阻隔、守静、进退不决、反背、止住、不见。"],["身体：手指、骨、鼻、背。"],["时序：冬春之月、十二月丑寅年月日时、七五十数月日、土年月日时。"],["静物：土石、瓜果、黄物、土中之物。"],["动物：虎、狗、鼠、百兽、",{text:"黔啄",glossary:"g12"},"之物。"],["家宅：安稳、诸事有阻、家人不睦、春占不安。"],["屋舍：东北方之居、山居近石、近路之宅。"],["饮食：土中物味、诸兽之肉、墓畔竹笋之属、野味。"],["婚姻：阻隔难成、成亦迟、利少男之婚、春占不利、宜对乡里婚。"],["求名：阻隔无名、宜东北方之任、宜土官山城之职。"],["求利：求财阻隔、宜山林中取财、春占不利、有损失。"],["生产：难生、有险阻之厄、宜向东北、春占有损。"],["交易：难成、有山林田土之交易、春占有失。"],["谋旺：阻隔难成、进退不决。"],["出行：不宜远行、有阻、宜近陆行。"],["谒见：不可见、有阻、宜见山林之人。"],["疾病：手指之疾、脾胃之疾。"],["官讼：贵人阻滞、官讼未解、牵连不决。"],["坟墓：东北之穴、山中之穴、春占不利、近路旁有石。"],["数目：五、七、十。"],["方道：东北方。"],["五色：黄。"],["五味：甘。"]]},{id:"sec-09",label:"☱ 兑卦　二　金",showLabel:!0,sentences:[["天时：雨泽、新月、星。"],["地理：泽、水际、缺池、废井、山崩破裂之地、其地为",{text:"刚卤",glossary:"g11"},"。"],["人物：少女、妾、歌妓、伶人、译人、巫师。"],["人事：喜悦、口、谗毁、谤说、饮食。"],["身体：舌、口喉、肺、痰、涎。"],["时序：秋八月、酉年月日时、二四九月日。"],["静物：金刀、金类、乐器、废物、缺器。"],["动物：羊、泽中之物。"],["屋舍：西向之居、近泽之居、败墙壁宅、户有损。"],["家宅：不安、防口舌、秋占喜悦、夏占家宅有祸。"],["饮食：羊肉、泽中之物、宿味、辛辣之味。"],["婚姻：不成、秋占可成、有喜、主成婚之吉、利婚少女、夏占不利。"],["生产：不利、恐有损胎或则生女、夏占不利、宜坐向西。"],["求名：难成、因名有损、利西之任、宜刑官、武职、伶官、译官。"],["求利：无利、有损、财利、主口舌、秋占有财喜、夏占破财。"],["出行：不宜远行、防口舌、或损失、宜西行、秋占宜行有利。"],["交易：难利、防口舌、有争竞、夏占不利、秋占有交易之财。"],["谋旺：难成、谋中有损、秋占有喜、夏占不遂。"],["谒见：利行西方、见有咒诅。"],["疾病：口舌、咽喉之疾、气逆喘疾、饮食不",{text:"飧",glossary:"g16"},"。"],["坟墓：宜西向、防穴中有水、近泽之墓、夏占不宜、或葬废穴。"],["官讼：争讼不已、曲直未决、因讼有损、防刑、秋占为体得理胜讼。"],["姓字：",{text:"商音",glossary:"g17"},"、带口带金字旁姓氏、行位四二九。"],["数目：四、二、九。"],["方道：西方。"],["五色：白。"],["五味：辛、辣。"]]}],glossary:[{id:"g01",term:"霰",pinyin:"xiàn",meaning:"雪珠，空中水汽遇冷凝结成的小冰粒"},{id:"g02",term:"公廨",pinyin:"gōng xiè",meaning:"官署，官府办公之所"},{id:"g03",term:"蕃鲜",pinyin:"fān xiān",meaning:"茂盛鲜嫩"},{id:"g04",term:"萑苇",pinyin:"huán wěi",meaning:"芦苇类植物"},{id:"g05",term:"风宪",pinyin:"fēng xiàn",meaning:"监察官员，掌风纪法宪之职"},{id:"g06",term:"肱",pinyin:"gōng",meaning:"上臂，肩至肘之间"},{id:"g07",term:"资贼",pinyin:"zī zéi",meaning:"盗贼，此处指坎卦险陷之人"},{id:"g08",term:"矫揉之物",pinyin:"jiǎo róu",meaning:"经过弯曲加工的器物，如弓"},{id:"g09",term:"痼冷",pinyin:"gù lěng",meaning:"久治不愈的寒冷之症"},{id:"g10",term:"干亢",pinyin:"gān kàng",meaning:"干燥高亢之地"},{id:"g11",term:"刚卤",pinyin:"gāng lǔ",meaning:"坚硬盐碱之地"},{id:"g12",term:"黔喙·黔啄",pinyin:"qián huì",meaning:"黑嘴的动物，泛指鸟兽"},{id:"g13",term:"山岚",pinyin:"shān lán",meaning:"山中雾气"},{id:"g14",term:"蓏",pinyin:"luǒ",meaning:"草本植物的果实"},{id:"g15",term:"阍寺",pinyin:"hūn sì",meaning:"守门人"},{id:"g16",term:"飧",pinyin:"sūn",meaning:"熟食，此处「不飧」指饮食不消化"},{id:"g17",term:"角音·征音·宫音·商音·羽音",pinyin:"—",meaning:"五音，对应五行：角木·征火·宫土·商金·羽水"}],"aria-label":"八卦类象与万物属类原文"}),t[2]||(t[2]=l(`<h2 id="🔤-注音与字词" tabindex="-1">🔤 注音与字词 <a class="header-anchor" href="#🔤-注音与字词" aria-label="Permalink to &quot;🔤 注音与字词&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字词</th><th>注音</th><th>释义</th></tr></thead><tbody><tr><td>霰</td><td>xiàn</td><td>雪珠，空中水汽遇冷凝结成的小冰粒</td></tr><tr><td>公廨</td><td>gōng xiè</td><td>官署，官府办公之所</td></tr><tr><td>蕃鲜</td><td>fān xiān</td><td>茂盛鲜嫩</td></tr><tr><td>萑苇</td><td>huán wěi</td><td>芦苇类植物</td></tr><tr><td>风宪</td><td>fēng xiàn</td><td>监察官员，掌风纪法宪之职</td></tr><tr><td>肱</td><td>gōng</td><td>上臂，肩至肘之间</td></tr><tr><td>资贼</td><td>zī zéi</td><td>盗贼，此处指坎卦险陷之人</td></tr><tr><td>矫揉之物</td><td>jiǎo róu</td><td>经过弯曲加工的器物，如弓</td></tr><tr><td>痼冷</td><td>gù lěng</td><td>久治不愈的寒冷之症</td></tr><tr><td>干亢</td><td>gān kàng</td><td>干燥高亢之地</td></tr><tr><td>刚卤</td><td>gāng lǔ</td><td>坚硬盐碱之地</td></tr><tr><td>黔喙·黔啄</td><td>qián huì</td><td>黑嘴的动物，泛指鸟兽</td></tr><tr><td>山岚</td><td>shān lán</td><td>山中雾气</td></tr><tr><td>蓏</td><td>luǒ</td><td>草本植物的果实</td></tr><tr><td>阍寺</td><td>hūn sì</td><td>守门人</td></tr><tr><td>飧</td><td>sūn</td><td>熟食，此处「不飧」指饮食不消化</td></tr><tr><td>角音·征音·宫音·商音·羽音</td><td>—</td><td>五音，对应五行：角木·征火·宫土·商金·羽水</td></tr></tbody></table><hr><h2 id="🧭-义理解析" tabindex="-1">🧭 义理解析 <a class="header-anchor" href="#🧭-义理解析" aria-label="Permalink to &quot;🧭 义理解析&quot;">​</a></h2><h3 id="一、两张表的关系" tabindex="-1">一、两张表的关系 <a class="header-anchor" href="#一、两张表的关系" aria-label="Permalink to &quot;一、两张表的关系&quot;">​</a></h3><p>本篇包含两张表，功能不同，互为补充：</p><table tabindex="0"><thead><tr><th></th><th>八卦类象（简表）</th><th>八卦万物属类（详表）</th></tr></thead><tbody><tr><td>性质</td><td>象的核心词，精炼</td><td>象的应用展开，详细</td></tr><tr><td>用途</td><td>起卦时快速取象</td><td>断卦时查询具体事项</td></tr><tr><td>与篇之二关系</td><td>精简版</td><td>详细版，两者互补</td></tr></tbody></table><p>篇之二的万物属类标注「并为上卦」，是<strong>起卦工具</strong>；<br> 篇之三的万物属类按天时·地理·人物·人事·身体·时序·动静物·屋舍·家宅·婚姻·饮食·生产·求名·谋旺·交易·求利·出行·谒见·疾病·官讼·坟墓·方道·五色·姓字·数目·五味二十余项展开，是<strong>断卦手册</strong>。</p><h3 id="二、每卦详表的内在结构" tabindex="-1">二、每卦详表的内在结构 <a class="header-anchor" href="#二、每卦详表的内在结构" aria-label="Permalink to &quot;二、每卦详表的内在结构&quot;">​</a></h3><p>每卦详表，隐含一个固定的判断逻辑：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>当令（旺季）→ 诸事顺遂</span></span>
<span class="line"><span>被克（衰季）→ 诸事不利</span></span></code></pre></div><p>以乾卦为例：</p><ul><li>秋占（金旺）：宅兴隆·婚宜成·生贵子·求名利·大利·得胜</li><li>夏占（火克金）：有祸·不利·损财·失理·大凶</li></ul><p>这个逻辑贯穿八卦所有事项，是断卦时最基本的时令判断框架。</p><h3 id="三、五音配五行" tabindex="-1">三、五音配五行 <a class="header-anchor" href="#三、五音配五行" aria-label="Permalink to &quot;三、五音配五行&quot;">​</a></h3><p>详表中「姓字」一栏出现五音，对应关系如下：</p><table tabindex="0"><thead><tr><th>五音</th><th>五行</th><th>对应卦</th></tr></thead><tbody><tr><td>宫音</td><td>土</td><td>坤、艮</td></tr><tr><td>商音</td><td>金</td><td>乾、兑</td></tr><tr><td>角音</td><td>木</td><td>震、巽</td></tr><tr><td>征音</td><td>火</td><td>离</td></tr><tr><td>羽音</td><td>水</td><td>坎</td></tr></tbody></table><p>这是古代通过人的姓名声音来判断五行属性的方法，与字形取象（带金旁·带木旁·点水旁）并用。</p><h3 id="四、数目系统说明" tabindex="-1">四、数目系统说明 <a class="header-anchor" href="#四、数目系统说明" aria-label="Permalink to &quot;四、数目系统说明&quot;">​</a></h3><p>各卦数目来源混用了两套系统：</p><table tabindex="0"><thead><tr><th>卦</th><th>数目</th><th>来源</th></tr></thead><tbody><tr><td>乾</td><td>一·四·九</td><td>先天数(一)·河图数(四·九)</td></tr><tr><td>坤</td><td>八·五·十</td><td>先天数(八)·河图数(五·十)</td></tr><tr><td>震</td><td>四·八·三</td><td>先天数(四·八)·河图数(三)</td></tr><tr><td>巽</td><td>五·三·八</td><td>先天数(五)·河图数(三·八)</td></tr><tr><td>坎</td><td>一·六</td><td>河图生成数（天一生水·地六成之）</td></tr><tr><td>离</td><td>三·二·七</td><td>先天数(三)·河图数(二·七)</td></tr><tr><td>艮</td><td>五·七·十</td><td>先天数(七)·河图数(五·十)</td></tr><tr><td>兑</td><td>四·二·九</td><td>先天数(二)·河图数(四·九)</td></tr></tbody></table><p>这与❓-007·008相关，目前理解为：<strong>先天数是起卦用，河图数是断卦取期用</strong>，两套数字在不同场景下各有侧重。待卷三「观梅数诀序」进一步印证。</p><hr><h2 id="🌀-象的感悟" tabindex="-1">🌀 象的感悟 <a class="header-anchor" href="#🌀-象的感悟" aria-label="Permalink to &quot;🌀 象的感悟&quot;">​</a></h2><h3 id="同五行-不同象" tabindex="-1">同五行，不同象 <a class="header-anchor" href="#同五行-不同象" aria-label="Permalink to &quot;同五行，不同象&quot;">​</a></h3><p>这张表最值得停留的地方，是<strong>同五行的卦，象却截然不同</strong>：</p><p><strong>乾与兑，同属金：</strong><br> 乾是<strong>天上的金</strong>——圆满、刚健、运行不息，金最完整的状态。<br> 兑是<strong>泽边的金</strong>——有缺口、开口、喜悦，金被打开的状态。</p><blockquote><p>同是金，一个是完整的圆，一个是有缺的口。</p></blockquote><p><strong>震与巽，同属木：</strong><br> 震是<strong>雷中的木</strong>——突发、震动、一击而起，木向上冲的力量。<br> 巽是<strong>风中的木</strong>——渗透、顺入、无声而动，木向旁延伸的力量。</p><blockquote><p>同是木，一个是劈开，一个是渗进去。</p></blockquote><p><strong>坤与艮，同属土：</strong><br> 坤是<strong>平地的土</strong>——无边无际，承载一切，静默包容。<br> 艮是<strong>山上的土</strong>——突起耸立，阻隔边界，止而不动。</p><blockquote><p>同是土，一个是铺展，一个是耸立。</p></blockquote><p>断卦时，不能只看五行，要感受具体是哪个卦的象。</p><h3 id="身体是最直接的象" tabindex="-1">身体是最直接的象 <a class="header-anchor" href="#身体是最直接的象" aria-label="Permalink to &quot;身体是最直接的象&quot;">​</a></h3><p>八卦配身体，每一个都有内在道理：</p><ul><li>乾配<strong>首</strong>——天在最高处，头在最高处</li><li>坤配<strong>腹</strong>——地承载万物，腹承载脏腑</li><li>震配<strong>足</strong>——雷动则行，足是行动之本</li><li>巽配<strong>股</strong>——风渗透延伸，股是延伸之处</li><li>坎配<strong>耳·血</strong>——水流有声，耳听；血液流动如水</li><li>离配<strong>目</strong>——火是光明，目感知光明</li><li>艮配<strong>手·鼻·背</strong>——山是边界，手触边界；鼻如山之突起；背是阻断之象</li><li>兑配<strong>口·舌</strong>——泽有开口，口是人的开口</li></ul><p>身体就是一个小宇宙，八卦就在身上。感受到了，就不需要背。</p><h3 id="离卦的有壳之物" tabindex="-1">离卦的有壳之物 <a class="header-anchor" href="#离卦的有壳之物" aria-label="Permalink to &quot;离卦的有壳之物&quot;">​</a></h3><p>离中虚——外实中空。</p><p>看离卦的动物：雉·龟·鳖·蟹·螺·蚌——全是有壳的。<br> 壳是硬的（外刚），里面是软的（内空）。</p><p>这不是巧合，是象的一致性在说话。<br> 所有属离的东西，都有「外表光鲜文彩，内里空」的特质。<br> 文书有纹理，甲胄有纹饰，火焰最亮处中心是暗的——这是离的象。</p><h3 id="末句的提醒" tabindex="-1">末句的提醒 <a class="header-anchor" href="#末句的提醒" aria-label="Permalink to &quot;末句的提醒&quot;">​</a></h3><blockquote><p>右万物之象，庶事之多不止于此。占者宜各以其类而推之耳。</p></blockquote><p>邵雍在这里说得很清楚：<strong>这张表列不完，要自己去推类</strong>。</p><p>表是起点，不是终点。当你遇到表里没有的东西，要能感受它属于哪个卦的象，然后推类而断。这与「推数又须明理」是同一个原则——规则给范围，感悟给答案。</p><hr><h2 id="📌-小结" tabindex="-1">📌 小结 <a class="header-anchor" href="#📌-小结" aria-label="Permalink to &quot;📌 小结&quot;">​</a></h2><p><strong>本节关键词</strong></p><ul><li>八卦类象（简表）：起卦快速取象</li><li>八卦万物属类（详表）：断卦查询手册，按二十余项事类展开</li><li>当令则旺·被克则衰：贯穿所有事项的时令判断框架</li><li>同五行不同象：乾兑·震巽·坤艮，各有差异，感受比记忆重要</li><li>身体配卦：首乾·腹坤·足震·股巽·耳血坎·目离·手鼻背艮·口舌兑</li><li>五音配五行：角木·征火·宫土·商金·羽水</li></ul><p><strong>规律提炼</strong></p><ol><li>每卦所有象，都有一个<strong>内在一致的核心意象</strong>，感受到核心，就能推类</li><li>断卦时：先查详表找对应事项 → 再结合体用生克 → 再看时令旺衰 → 综合判断</li><li>表是工具，象是灵魂——「占者宜各以其类而推之」</li></ol><p><strong>与前文呼应</strong></p><ul><li>篇之二万物属类是「起卦用」，篇之三是「断卦用」，两张表配合使用</li><li>1-2节的八宫五行在这里得到完整展开</li><li>「推数又须明理」的原则，在末句「占者宜各以其类而推之」中再次印证</li></ul><hr><h2 id="❓-存疑" tabindex="-1">❓ 存疑 <a class="header-anchor" href="#❓-存疑" aria-label="Permalink to &quot;❓ 存疑&quot;">​</a></h2><blockquote><p><strong>❓****-007 / <strong><strong>❓</strong></strong>-008</strong>（合并）：各卦数目混用了先天数与河图数两套系统，目前理解为先天数用于起卦，河图数用于断卦取期。待卷三「观梅数诀序」章节进一步印证。</p></blockquote>`,56))])}const q=a(g,[["render",h]]);export{y as __pageData,q as default};
